(()=>{const canvas=document.querySelector('#cad-canvas'),ctx=canvas.getContext('2d'),run=document.querySelector('#draw');let W=0,H=0,view='parts',running=false,active=-1,progress=1,done=0,stage='idle',layout=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const parts=[{name:'Deck plate',w:1400,h:800,color:'#79c4e3',points:[[0,0],[1400,0],[1400,650],[1200,800],[0,800]],holes:[[180,170,45],[1200,170,45]]},{name:'Hull frame',w:1100,h:900,color:'#8cd4b0',points:[[0,0],[1100,0],[1100,900],[900,900],[900,210],[200,210],[200,900],[0,900]],holes:[]},{name:'Bulkhead panel',w:900,h:1000,color:'#c4aadf',points:[[0,0],[900,0],[900,800],[700,1000],[200,1000],[0,800]],holes:[[450,460,150]]},{name:'Mount bracket',w:600,h:450,color:'#dfb579',points:[[0,0],[600,0],[600,140],[180,140],[180,450],[0,450]],holes:[[90,330,35],[470,70,30]]}];
function nest(){const placements=[],padding=100;let x=padding,y=padding,rowH=0;for(const part of parts){if(x+part.w+padding>4000){x=padding;y+=rowH+padding;rowH=0}placements.push({x,y,part});x+=part.w+padding;rowH=Math.max(rowH,part.h)}return placements}
function check(){let errors=0;for(let i=0;i<layout.length;i++){const a=layout[i];if(a.x<0||a.y<0||a.x+a.part.w>4000||a.y+a.part.h>2400)errors++;for(let j=i+1;j<layout.length;j++){const b=layout[j];if(a.x<b.x+b.part.w&&a.x+a.part.w>b.x&&a.y<b.y+b.part.h&&a.y+a.part.h>b.y)errors++}}return errors}
function agent(id){stage=id;document.querySelectorAll('[data-agent]').forEach(el=>{el.classList.toggle('active',el.dataset.agent===id);if(['draft','nest','check'].indexOf(el.dataset.agent)<['draft','nest','check'].indexOf(id))el.classList.add('finished');el.querySelector('b').textContent=el.classList.contains('finished')?'✓':el.dataset.agent===id?'●':'○'})}
function command(text){document.querySelector('#command').textContent=text}
function strokePath(p,origin,scale,color,fraction=1){const verts=[...p.points,p.points[0]],lens=[];let length=0;for(let i=1;i<verts.length;i++){const l=Math.hypot(verts[i][0]-verts[i-1][0],verts[i][1]-verts[i-1][1]);lens.push(l);length+=l}let remaining=length*fraction,cursor=verts[0];ctx.beginPath();ctx.moveTo(origin.x+verts[0][0]*scale,origin.y+verts[0][1]*scale);for(let i=1;i<verts.length;i++){const l=lens[i-1],t=Math.min(1,remaining/l);if(remaining<=0)break;cursor=[verts[i-1][0]+(verts[i][0]-verts[i-1][0])*t,verts[i-1][1]+(verts[i][1]-verts[i-1][1])*t];ctx.lineTo(origin.x+cursor[0]*scale,origin.y+cursor[1]*scale);remaining-=l}ctx.strokeStyle=color;ctx.lineWidth=1.8;ctx.stroke();if(fraction===1){p.holes.forEach(([x,y,r])=>{ctx.beginPath();ctx.arc(origin.x+x*scale,origin.y+y*scale,r*scale,0,Math.PI*2);ctx.stroke()})}return{x:origin.x+cursor[0]*scale,y:origin.y+cursor[1]*scale}}
function robot(x,y,color){ctx.fillStyle=color;ctx.fillRect(x-7,y-21,14,12);ctx.fillRect(x-4,y-9,8,6);ctx.fillStyle='#123042';ctx.fillRect(x-4,y-18,3,3);ctx.fillRect(x+1,y-18,3,3);ctx.fillStyle='#bbd8e5';ctx.fillRect(x-5,y-3,3,4);ctx.fillRect(x+2,y-3,3,4)}
function draw(){ctx.fillStyle='#10202b';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#203744';ctx.lineWidth=.5;for(let x=0;x<W;x+=25){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.font='13px Arial';ctx.textAlign='left';
if(view==='parts'){const cols=2,cellW=W/cols,cellH=(H-30)/2;parts.forEach((p,i)=>{const col=i%2,row=Math.floor(i/2),k=Math.min((cellW-55)/p.w,(cellH-55)/p.h),o={x:col*cellW+(cellW-p.w*k)/2,y:row*cellH+35+(cellH-55-p.h*k)/2};const fraction=running&&stage==='draft'?(i<active?1:i===active?progress:0):1;strokePath(p,o,k,running&&stage==='draft'&&i>active?'#385262':p.color,fraction||1);if(running&&stage==='draft'&&i===active){const q=strokePath(p,o,k,p.color,progress);robot(q.x,q.y,p.color)}ctx.fillStyle=p.color;ctx.fillText(p.name,col*cellW+22,(row+1)*cellH+14);ctx.fillStyle='#7895a6';ctx.font='12px Arial';ctx.fillText(`${p.w} × ${p.h} mm`,col*cellW+22,(row+1)*cellH+30);ctx.font='13px Arial'})}else{const k=Math.min((W-65)/4000,(H-70)/2400),o={x:(W-4000*k)/2,y:(H-2400*k)/2+5};ctx.strokeStyle='#b0c6ce';ctx.lineWidth=1.4;ctx.strokeRect(o.x,o.y,4000*k,2400*k);ctx.fillStyle='#93adb9';ctx.fillText('Stock plate · 4000 × 2400 mm',o.x,o.y-12);layout.forEach(({part,x,y},i)=>{strokePath(part,{x:o.x+x*k,y:o.y+y*k},k,part.color);ctx.fillStyle=part.color;ctx.font='12px Arial';ctx.fillText(String(i+1),o.x+(x+part.w/2)*k,o.y+(y+part.h/2)*k)});if(running&&(stage==='nest'||stage==='check'))robot(o.x+3700*k,o.y+1900*k,stage==='nest'?'#dfb579':'#8cd4b0')}
}
const inviteObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){run.classList.add("demo-visible");inviteObserver.disconnect()}},{threshold:.7});inviteObserver.observe(run);
function animate(ms,update){return new Promise(resolve=>{const start=performance.now();function frame(t){const p=Math.min(1,(t-start)/(reduced?90:ms));update(p);draw();if(p<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})}
async function generate(){if(running)return;run.classList.remove("demo-invite");running=true;run.disabled=true;run.textContent='Agents working…';document.querySelectorAll('[data-agent]').forEach(e=>e.classList.remove('finished'));setView('parts');agent('draft');for(let i=0;i<parts.length;i++){active=i;command(`PLINE / CIRCLE — ${parts[i].name}, ${parts[i].w} × ${parts[i].h} mm`);await animate(700,p=>progress=p)}document.querySelector('[data-agent="draft"]').classList.add('finished');agent('nest');layout=nest();setView('nest');command('Nest agent places the four components inside the stock plate.');await animate(950,()=>{});document.querySelector('[data-agent="nest"]').classList.add('finished');agent('check');command('Check agent compares part bounds for overlap and plate limits.');await animate(850,()=>{});const errors=check();document.querySelectorAll('[data-agent]').forEach(el=>{el.classList.remove('active');el.classList.add('finished');el.querySelector('b').textContent='✓'});document.querySelector('#cad-status').textContent=`4 components · ${errors} layout issues`;command(errors?'Layout needs review.':'Layout checked: all four parts fit the plate with no bounding-box overlaps.');stage='done';running=false;run.disabled=false;run.textContent='Replay drawing & nesting →';draw()}
function setView(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===next)));document.querySelector('#view-label').textContent=next==='parts'?'TOP / COMPONENT DETAILS':'TOP / STOCK PLATE';draw()}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;const ratio=Math.min(devicePixelRatio,2);canvas.width=W*ratio;canvas.height=H*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);draw()}layout=nest();new ResizeObserver(resize).observe(canvas);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(!running)setView(b.dataset.view)});run.onclick=generate;resize()})();
